UPDATE `sourcelead`.`EMAIL_SCENARIO` SET `BODY`='Welcome !!!\n\nDear {{Registration.FirstName}} {{Registration.LastName}},\n\nIt\'s great to see that you\'ve started accessing sourcelead\n\n{{Registration.LoginURL}}\n\nI hope you will have a wonderful time with SourceLead. If you have any questions or comments, feel free to reach out to us at support@sourcelead.com' WHERE `ID`='1';
UPDATE `sourcelead`.`EMAIL_SCENARIO` SET `BODY`='Dear {{ForgotPassword.FirstName}} {{ForgotPassword.LastName}},\n\nWe received a request to reset your password for your SourceLead account.\n\nVerification Code : {{ForgotPassword.verificationCode}}\n\nTo reset your password process simply click the link below\n\n{{ForgotPassword.ResetPasswordURL}}\n\nIf you didn\'t ask to change your password ,don\'t worry! Your password is still safe and access the sourcelead with existing credentials.' WHERE `ID`='2';
UPDATE `sourcelead`.`EMAIL_SCENARIO` SET `BODY`='Dear {{UpdatePassword.FirstName}} {{UpdatePassword.LastName}},\n\nThe Password of your Sourcelead  has been reset successfully.\n\nYou can now log in to your Sourcelead application with your new password. If you do not request for new password please contact support@sourcelead.com' WHERE `ID`='3';
UPDATE `sourcelead`.`EMAIL_SCENARIO` SET `BODY`='Dear {{InviteUser.FirstName}} {{InviteUser.LastName}},\n\n{{InviteUser.AdministratorFirstName}} {{InviteUser.AdministratorLastName}} invited you to SourceLead as a {{InviteUser.Role}}.\n\nYou can simply login into SourceLead by clicking below link with follow credentials\n\n{{InviteUser.LoginURL}}\n\nLogin Username : {{InviteUser.UserEmailId}}\n\nPassword : {{InviteUser.Password}}' WHERE `ID`='4';
UPDATE `sourcelead`.`EMAIL_SCENARIO` SET `BODY`='Dear {{ManagerAssignedToProject.ManagerFirstName}} {{ManagerAssignedToProject.ManagerLastName}},\n\n{{ManagerAssignedToProject.UserEmailId}} assigned as a project manager for the {{ManagerAssignedToProject.ProjectName}} to the\n\n{{ManagerAssignedToProject.ClientName}}.\n\nTeam Members\n\n{{ManagerAssignedToProject.TeamMembers}}.' WHERE `ID`='5';
UPDATE `sourcelead`.`EMAIL_SCENARIO` SET `BODY`='Dear {{TeamAssignedToProject.EmployeeFirstName}} {{TeamAssignedToProject.EmployeeLastName}},\n\n{{TeamAssignedToProject.UserEmailId}} assigned you as a team member for the {{TeamAssignedToProject.ProjectName}} and your project manager is\n\n{{TeamAssignedToProject.ManagerFirstName}} {{TeamAssignedToProject.ManagerLastName}}.' WHERE `ID`='6';
UPDATE `sourcelead`.`EMAIL_SCENARIO` SET `BODY`='Dear {{TimeSheetSubmission.ApproverFirstName}} {{TimeSheetSubmission.ApproverLastName}},\n\n{{TimeSheetSubmission.FirstName}} {{TimeSheetSubmission.LastName}} have submitted timesheet for approval from {{TimeSheetSubmission.TimeFrequency}}.\n\nProject Name : {{TimeSheetSubmission.ProjectName}}\n\nClient : {{TimeSheetSubmission.ClientName}}\n\nInvoice Frequency : {{TimeSheetSubmission.InvoiceFrequency}}' WHERE `ID`='7';
UPDATE `sourcelead`.`EMAIL_SCENARIO` SET `BODY`='Dear {{TimeSheetSubmission.ApproverFirstName}} {{TimeSheetSubmission.ApproverLastName}},\n\n{{TimeSheetSubmission.FirstName}} {{TimeSheetSubmission.LastName}} have submitted timesheet for approval from {{TimeSheetSubmission.TimeFrequency}}.\n\nProject Name : {{TimeSheetSubmission.ProjectName}}\n\nClient : {{TimeSheetSubmission.ClientName}}\n\nInvoice Frequency : {{TimeSheetSubmission.InvoiceFrequency}}' WHERE `ID`='9';
